from pathlib import Path
import json
names='Crear usuarios por rol|Iniciar sesión|Bloquear cuenta tras intentos fallidos|Desactivar y reactivar usuarios|Restablecer contraseña|Verificar acceso en dos pasos|Consultar auditoría|Crear productos y generar SKU|Registrar códigos de barras|Definir presentaciones y factores|Editar con control de concurrencia|Dar de baja sin stock|Detectar nombres similares|Consultar producto y stock por código|Gestionar categorías y marcas|Definir políticas de stock|Conservar ledger inmutable|Impedir saldo negativo|Controlar reintentos idempotentes|Calcular costo promedio|Trasladar stock atómicamente|Consultar kardex|Conciliar inventario por horario|Crear borrador de recepción|Confirmar recepción|Convertir cajas a unidades|Anular borrador de recepción|Transferir de bodega a venta|Solicitar ajuste o merma|Aprobar o rechazar ajustes|Registrar ajuste directo menor|Crear conteo y congelar alcance|Contar a ciegas y registrar hallazgos|Recontar diferencias|Cerrar conteo y medir exactitud|Anular conteo y descongelar|Importar ventas del POS|Descargar errores de importación|Impedir confirmar archivo repetido|Generar ubicaciones en lote|Administrar estado de ubicación|Gestionar proveedores y RUC|Asociar proveedores preferidos|Consultar agotados y mínimos|Exportar pedido sugerido|Consultar tablero del día|Enviar alertas externas|Consultar inventario valorizado|Analizar rotación y clase ABC|Consultar mermas y responsables|Descargar reportes|Importar catálogo inicial|Cargar apertura por ubicación|Escanear con cámara móvil|Operar sin conexión y sincronizar|Capturar conteos y recepciones móviles|Verificar límites entre capas|Verificar análisis estático y formato|Bloquear código roto en CI|Respaldar y probar restauración|Publicar con HTTPS y protección|Evaluar carga y seguridad|Evaluar calidad y aplicar SUS'.split('|')
assert len(names)==63
Path('audit_work/usecase_names.json').write_text(json.dumps({f'HU-{i+1:03}':n for i,n in enumerate(names)},ensure_ascii=False),encoding='utf-8')
